-- query: SELECT toStartOfMonth(date) AS month, project, version, sum(count) AS downloads FROM pypi.pypi_downloads_per_day_by_version WHERE project IN ('nvidia-cuda-runtime-cu11','nvidia-cuda-runtime-cu12','nvidia-cuda-runtime','nvidia-cuda-runtime-cu13') AND date >= '2025-01-01' GROUP BY month, project, version ORDER BY month, project, version FORMAT CSVWithNames
-- SELECT toStartOfMonth(date) m, project, sum(count) FROM pypi.pypi_downloads_per_day WHERE project IN ('torch','cuda-toolkit','nvidia-cuda-runtime','nvidia-cuda-runtime-cu12','numpy','jax-cuda12-plugin','jax-cuda13-plugin','onnxruntime-gpu','cupy-cuda12x','cupy-cuda13x','cupy-cuda11x','llama-cpp-python','vllm') AND date>='2025-01-01' GROUP BY m, project ORDER BY project, m FORMAT CSVWithNames
